-- 28 original clinical reasoning cases. Not official ENARM questions.
BEGIN;
INSERT INTO public.tedvio_enarm2027_questions
 (slug,area,topic,difficulty,vignette,prompt,options,correct_index,rationale,reference_hint)
SELECT x.slug,x.area,x.topic,x.difficulty,x.vignette,x.prompt,x.options,x.correct_index::smallint,x.rationale,x.reference_hint
FROM jsonb_to_recordset($enarmcases$[{"slug":"mi-reperf","area":"medicina_interna","topic":"Síndrome coronario agudo","vignette":"Varón de 61 años con dolor opresivo, diaforesis y elevación persistente del ST anterior durante 50 minutos; hemodinamia está disponible.","prompt":"¿Cuál es la estrategia preferida?","difficulty":"avanzado","options":["Observación sin reperfusión","Angioplastia coronaria primaria oportuna","Prueba de esfuerzo inmediata","Alta y control ambulatorio"],"correct_index":1,"rationale":"El infarto con elevación del ST requiere reperfusión urgente. Se prefiere intervención coronaria percutánea primaria cuando está disponible oportunamente.","reference_hint":"Consultar GPC clínicas vigentes y textos de Medicina Interna; corroborar actualización."},{"slug":"mi-dka-k","area":"medicina_interna","topic":"Cetoacidosis diabética","vignette":"Mujer de 23 años con DM1, vómitos, glucemia 420 mg/dL, pH 7.12, bicarbonato 9, cetonas elevadas y potasio de 2.9 mEq/L.","prompt":"¿Qué debe hacerse antes de iniciar insulina intravenosa?","difficulty":"intermedio","options":["Administrar bicarbonato rutinario","Iniciar insulina a dosis doble","Corregir hipopotasemia y monitorizar","Suspender líquidos intravenosos"],"correct_index":2,"rationale":"La insulina desplaza el potasio al interior celular. Ante hipopotasemia importante se requiere reposición de potasio antes de iniciar insulina para evitar arritmias.","reference_hint":"Consultar GPC clínicas vigentes y textos de Medicina Interna; corroborar actualización."},{"slug":"mi-hiperk","area":"medicina_interna","topic":"Hiperpotasemia","vignette":"Paciente con enfermedad renal presenta potasio 7.1 mEq/L, ondas T picudas y ensanchamiento de QRS en monitor cardíaco.","prompt":"¿Cuál es el tratamiento inmediato de estabilización cardiaca?","difficulty":"intermedio","options":["Gluconato de calcio intravenoso","Solo restricción dietética","Furosemida oral como única medida","Bicarbonato oral diferido"],"correct_index":0,"rationale":"Ante hiperpotasemia con cambios electrocardiográficos, el calcio intravenoso estabiliza la membrana miocárdica mientras se realizan medidas para reducir el potasio.","reference_hint":"Consultar GPC clínicas vigentes y textos de Medicina Interna; corroborar actualización."},{"slug":"mi-asma","area":"medicina_interna","topic":"Asma","vignette":"Mujer de 27 años con sibilancias episódicas, tos nocturna y síntomas después de ejercicio; presenta obstrucción reversible en espirometría.","prompt":"¿Cuál es el diagnóstico más probable?","difficulty":"intermedio","options":["Fibrosis pulmonar idiopática","Enfermedad pulmonar restrictiva","Embolia pulmonar crónica","Asma bronquial"],"correct_index":3,"rationale":"Los síntomas respiratorios variables asociados a reversibilidad de la limitación del flujo aéreo orientan a asma; se debe confirmar la variabilidad funcional.","reference_hint":"Consultar GPC clínicas vigentes y textos de Medicina Interna; corroborar actualización."},{"slug":"ped-bronquiolitis","area":"pediatria","topic":"Bronquiolitis","vignette":"Lactante de 7 meses con rinorrea, sibilancias y tos de tres días. Saturación 97% en aire ambiente y adecuada alimentación.","prompt":"¿Cuál es el manejo inicial más apropiado?","difficulty":"basico","options":["Antibióticos de rutina","Corticoides sistémicos universales","Soporte, higiene nasal e hidratación","Salbutamol programado para todos"],"correct_index":2,"rationale":"La bronquiolitis sin datos de gravedad se trata principalmente con medidas de soporte. Los broncodilatadores, antibióticos y esteroides no se usan de manera sistemática.","reference_hint":"Consultar GPC vigentes de Pediatría y textos de urgencias pediátricas."},{"slug":"ped-crup","area":"pediatria","topic":"Laringotraqueítis","vignette":"Niño de 2 años con tos perruna, estridor en reposo y tiraje moderado. No presenta babeo ni aspecto tóxico.","prompt":"¿Qué tratamiento corresponde a este cuadro?","difficulty":"avanzado","options":["Solo humidificación","Dexametasona y adrenalina nebulizada","Antitusígeno opioide","Antibiótico oral sin evaluación"],"correct_index":1,"rationale":"El crup con estridor en reposo requiere dexametasona, además de adrenalina nebulizada y observación cuando existe obstrucción moderada o grave.","reference_hint":"Consultar GPC vigentes de Pediatría y textos de urgencias pediátricas."},{"slug":"ped-invaginacion","area":"pediatria","topic":"Invaginación intestinal","vignette":"Lactante de 10 meses con dolor abdominal intermitente, vómitos y ultrasonido con imagen en diana, estable y sin peritonitis.","prompt":"¿Cuál es el tratamiento inicial de elección?","difficulty":"intermedio","options":["Reducción por enema guiado","Laxantes estimulantes","Antiespasmódicos exclusivos","Endoscopia alta"],"correct_index":0,"rationale":"En invaginación estable sin perforación ni peritonitis, el enema neumático o hidrostático guiado es una estrategia inicial de elección con respaldo quirúrgico.","reference_hint":"Consultar GPC vigentes de Pediatría y textos de urgencias pediátricas."},{"slug":"ped-kawasaki","area":"pediatria","topic":"Enfermedad de Kawasaki","vignette":"Paciente de 4 años con seis días de fiebre, conjuntivitis no purulenta, labios fisurados, edema de manos, exantema y adenopatía cervical.","prompt":"¿Qué tratamiento específico disminuye complicaciones coronarias?","difficulty":"intermedio","options":["Amoxicilina oral","Antihistamínicos exclusivos","Esperar resolución sin valoración","Inmunoglobulina IV y manejo antiinflamatorio indicado"],"correct_index":3,"rationale":"La enfermedad de Kawasaki requiere inmunoglobulina intravenosa temprana para reducir lesiones coronarias, con evaluación cardiológica y manejo antiinflamatorio individualizado.","reference_hint":"Consultar GPC vigentes de Pediatría y textos de urgencias pediátricas."},{"slug":"go-eclampsia","area":"ginecologia_obstetricia","topic":"Eclampsia","vignette":"Embarazada de 32 semanas con presión 175/115 mmHg, cefalea intensa y convulsión generalizada; se aplican medidas iniciales de soporte.","prompt":"¿Qué anticonvulsivo está indicado para prevenir recurrencia?","difficulty":"basico","options":["Diazepam oral aislado","Sulfato de magnesio","Fenitoína rutinaria","Antibioterapia empírica"],"correct_index":1,"rationale":"El sulfato de magnesio es el anticonvulsivo de elección en eclampsia, además de estabilizar a la madre, tratar hipertensión grave y planear resolución obstétrica.","reference_hint":"Consultar GPC de Obstetricia, recomendaciones OMS y NOM-007 vigente."},{"slug":"go-ectopico","area":"ginecologia_obstetricia","topic":"Embarazo ectópico","vignette":"Mujer con amenorrea de siete semanas y prueba positiva, dolor pélvico intenso, síncope, TA 80/50 y líquido libre en ultrasonido.","prompt":"¿Cuál es el manejo prioritario?","difficulty":"intermedio","options":["Metotrexato ambulatorio","Repetir ultrasonido en dos semanas","Reanimación y tratamiento quirúrgico urgente","Progestágenos para conservar gestación"],"correct_index":2,"rationale":"La inestabilidad y el líquido libre sugieren embarazo ectópico roto; es una emergencia quirúrgica que requiere reanimación y control de hemorragia.","reference_hint":"Consultar GPC de Obstetricia, recomendaciones OMS y NOM-007 vigente."},{"slug":"go-previa","area":"ginecologia_obstetricia","topic":"Placenta previa","vignette":"Gestante de 33 semanas con sangrado rojo brillante indoloro y estabilidad materno-fetal. Aún no se localiza la placenta mediante ultrasonido.","prompt":"¿Qué exploración debe evitarse hasta excluir placenta previa?","difficulty":"avanzado","options":["Tacto vaginal digital","Ultrasonido abdominal","Evaluación hemodinámica","Monitoreo fetal"],"correct_index":0,"rationale":"Ante hemorragia del tercer trimestre compatible con placenta previa debe evitarse tacto vaginal digital hasta localizar la placenta, por riesgo de sangrado importante.","reference_hint":"Consultar GPC de Obstetricia, recomendaciones OMS y NOM-007 vigente."},{"slug":"go-atonia","area":"ginecologia_obstetricia","topic":"Hemorragia posparto","vignette":"Durante el puerperio inmediato aparece sangrado profuso con útero blando y aumentado de tamaño después de expulsión placentaria.","prompt":"¿Cuál es la intervención inicial orientada a la causa probable?","difficulty":"intermedio","options":["Observar sin tratamiento","Hierro oral exclusivamente","Tomografía antes de reanimar","Masaje uterino, oxitocina y reanimación"],"correct_index":3,"rationale":"La atonía uterina es causa frecuente de hemorragia posparto. El manejo temprano incluye masaje, uterotónicos y reanimación mientras se descartan otras causas.","reference_hint":"Consultar GPC de Obstetricia, recomendaciones OMS y NOM-007 vigente."},{"slug":"cir-apendicitis","area":"cirugia","topic":"Apendicitis aguda","vignette":"Varón de 20 años con dolor que comenzó periumbilical y migró a fosa ilíaca derecha, anorexia, náuseas y defensa localizada.","prompt":"¿Cuál es el diagnóstico más probable?","difficulty":"basico","options":["Colecistitis aguda","Apendicitis aguda","Pancreatitis aguda","Diverticulitis sigmoidea"],"correct_index":1,"rationale":"La migración típica del dolor hacia la fosa ilíaca derecha, junto con síntomas gastrointestinales y defensa localizada, sugiere apendicitis aguda.","reference_hint":"Consultar GPC de cirugía general y criterios de urgencias abdominales."},{"slug":"cir-colecistitis","area":"cirugia","topic":"Colecistitis aguda","vignette":"Mujer de 45 años con dolor en hipocondrio derecho de veinte horas, fiebre, Murphy positivo y ultrasonido con pared engrosada y litiasis.","prompt":"¿Cuál es el diagnóstico más probable?","difficulty":"intermedio","options":["Pancreatitis autoinmune","Colangitis esclerosante","Colecistitis aguda litiásica","Cólico biliar simple"],"correct_index":2,"rationale":"La combinación de dolor prolongado, fiebre, Murphy positivo y hallazgos inflamatorios ecográficos es típica de colecistitis aguda litiásica.","reference_hint":"Consultar GPC de cirugía general y criterios de urgencias abdominales."},{"slug":"cir-pancreatitis","area":"cirugia","topic":"Pancreatitis aguda","vignette":"Hombre de 48 años con dolor epigástrico irradiado a espalda, vómitos y lipasa mayor de cinco veces el límite normal, sin choque.","prompt":"¿Cuál es un componente esencial del tratamiento temprano?","difficulty":"intermedio","options":["Líquidos IV individualizados y analgesia","Antibiótico profiláctico universal","Nutrición parenteral obligatoria","Cirugía pancreática inmediata"],"correct_index":0,"rationale":"La pancreatitis requiere analgesia, hidratación ajustada con reevaluación y nutrición enteral temprana según tolerancia; los antibióticos profilácticos no se indican rutinariamente.","reference_hint":"Consultar GPC de cirugía general y criterios de urgencias abdominales."},{"slug":"cir-obstruccion","area":"cirugia","topic":"Obstrucción intestinal","vignette":"Mujer de 68 años con antecedente de laparotomía, vómitos biliosos, distensión y niveles hidroaéreos de intestino delgado, sin peritonitis.","prompt":"¿Cuál es una estrategia inicial apropiada?","difficulty":"avanzado","options":["Antidiarreicos y alta","Colonoscopia para todos","Alimentación oral abundante","Líquidos IV y descompresión según indicación"],"correct_index":3,"rationale":"En obstrucción de intestino delgado se inicia corrección hidroelectrolítica, descompresión si está indicada y vigilancia para identificar estrangulación o isquemia.","reference_hint":"Consultar GPC de cirugía general y criterios de urgencias abdominales."},{"slug":"urg-anafilaxia","area":"urgencias","topic":"Anafilaxia","vignette":"Minutos después de recibir un antibiótico, paciente desarrolla urticaria, sibilancias, edema labial e hipotensión de 75/45 mmHg.","prompt":"¿Cuál es el fármaco de primera elección?","difficulty":"basico","options":["Difenhidramina oral","Salbutamol exclusivo","Adrenalina IM en muslo anterolateral","Prednisona oral sin apoyo"],"correct_index":2,"rationale":"La anafilaxia es una urgencia. La adrenalina intramuscular es el tratamiento de primera línea; requiere también soporte y monitorización.","reference_hint":"Consultar guías actualizadas de urgencias, soporte vital y reanimación."},{"slug":"urg-neumotorax","area":"urgencias","topic":"Neumotórax a tensión","vignette":"Tras trauma torácico, adulto tiene disnea severa, hipotensión, ausencia unilateral de ruidos respiratorios e ingurgitación yugular.","prompt":"¿Cuál es la siguiente intervención?","difficulty":"intermedio","options":["Descompresión pleural inmediata","Esperar tomografía","Solicitar espirometría","Prueba de caminata"],"correct_index":0,"rationale":"El neumotórax a tensión con compromiso hemodinámico es un diagnóstico clínico que necesita descompresión urgente sin esperar radiografía.","reference_hint":"Consultar guías actualizadas de urgencias, soporte vital y reanimación."},{"slug":"urg-ictus","area":"urgencias","topic":"Evento vascular cerebral","vignette":"Mujer de 72 años con hemiparesia y afasia súbitas hace 65 minutos, glucosa capilar normal y sin neuroimagen previa.","prompt":"¿Qué estudio se requiere antes de decidir reperfusión?","difficulty":"intermedio","options":["Electroencefalograma","Radiografía de cráneo","RM de columna cervical","TC cerebral simple para descartar hemorragia"],"correct_index":3,"rationale":"En ictus agudo, la neuroimagen urgente permite distinguir enfermedad isquémica de hemorragia antes de valorar reperfusión y contraindicaciones.","reference_hint":"Consultar guías actualizadas de urgencias, soporte vital y reanimación."},{"slug":"urg-sepsis","area":"urgencias","topic":"Sepsis con hipoperfusión","vignette":"Varón febril de 66 años con probable pielonefritis, confusión, TA 82/49 mmHg y lactato 4.5 mmol/L en urgencias.","prompt":"¿Qué conjunto de medidas se prioriza?","difficulty":"intermedio","options":["Esperar cultivos positivos","Antimicrobianos tempranos y cristaloides reevaluados","Diuréticos como primera medida","Alta con antibiótico oral"],"correct_index":1,"rationale":"La sepsis con hipoperfusión requiere reconocimiento, antibióticos oportunos, reanimación individualizada con cristaloides y vasopresores si persiste hipotensión.","reference_hint":"Consultar guías actualizadas de urgencias, soporte vital y reanimación."},{"slug":"mf-adherencia","area":"medicina_familiar","topic":"Adherencia terapéutica","vignette":"Paciente de 56 años con diabetes y HbA1c 10%, omite medicación por costos y horarios laborales variables, además de faltar a controles.","prompt":"¿Cuál es el enfoque más efectivo para planificar seguimiento?","difficulty":"avanzado","options":["Reprender a la paciente","Suspender atención","Explicar sin preguntar","Explorar barreras y acordar decisiones compartidas"],"correct_index":3,"rationale":"Las decisiones compartidas y la exploración de costos, rutinas y preferencias permiten establecer metas realistas y mejorar la adherencia.","reference_hint":"Consultar guías de Atención Primaria, Medicina Familiar y prevención."},{"slug":"mf-tabaco","area":"medicina_familiar","topic":"Cesación tabáquica","vignette":"Adulto de 52 años con hipertensión refiere fumar 15 cigarrillos diarios y duda si podrá dejar el hábito. No tiene síntomas agudos.","prompt":"¿Qué intervención conviene iniciar en atención primaria?","difficulty":"intermedio","options":["Consejería breve y oferta de apoyo","No mencionar tabaco","Solicitar tomografía de rutina","Antibiótico preventivo"],"correct_index":0,"rationale":"La consejería breve con evaluación de disposición al cambio y oferta de tratamiento conductual y farmacológico reduce el riesgo por tabaquismo.","reference_hint":"Consultar guías de Atención Primaria, Medicina Familiar y prevención."},{"slug":"mf-polifarmacia","area":"medicina_familiar","topic":"Polifarmacia en personas mayores","vignette":"Mujer de 79 años con caídas y somnolencia, uso prolongado de benzodiacepinas e ingesta de otros siete medicamentos, sin epilepsia.","prompt":"¿Cuál es la intervención más apropiada?","difficulty":"intermedio","options":["Agregar otro sedante","Duplicar hipnótico","Revisar fármacos y planear retirada gradual si corresponde","No revisar por la edad"],"correct_index":2,"rationale":"Las benzodiacepinas aumentan riesgo de sedación y caídas en personas mayores. Una revisión integral puede indicar desprescripción gradual y alternativas.","reference_hint":"Consultar guías de Atención Primaria, Medicina Familiar y prevención."},{"slug":"mf-riesgo-cv","area":"medicina_familiar","topic":"Riesgo cardiovascular","vignette":"Varón de 59 años con hipertensión, obesidad abdominal, sedentarismo y antecedentes familiares de infarto solicita prevención cardiovascular.","prompt":"¿Qué estrategia debe guiar el plan?","difficulty":"intermedio","options":["Aspirina para todos","Valorar riesgo global y factores modificables","Reposo físico permanente","Atender solo la presión"],"correct_index":1,"rationale":"La prevención cardiovascular requiere valorar riesgo global, lípidos, tabaquismo, alimentación, ejercicio y preferencias, evitando medidas universales no indicadas.","reference_hint":"Consultar guías de Atención Primaria, Medicina Familiar y prevención."},{"slug":"sp-rr","area":"salud_publica","topic":"Riesgo relativo","vignette":"En un brote, enferman 18 de 60 expuestos a un alimento y 4 de 40 no expuestos; se comparan los riesgos de enfermedad.","prompt":"¿Cuál es el riesgo relativo aproximado?","difficulty":"basico","options":["0.33","1.50","2.00","3.00"],"correct_index":3,"rationale":"El ataque en expuestos es 18/60 = 0.30 y en no expuestos 4/40 = 0.10. El cociente de riesgos es 3.0.","reference_hint":"Consultar textos vigentes de epidemiología clínica y salud pública."},{"slug":"sp-especificidad","area":"salud_publica","topic":"Especificidad","vignette":"En un estudio de prueba diagnóstica hay 120 pacientes sin enfermedad; 90 tienen prueba negativa y 30 una prueba falsamente positiva.","prompt":"¿Cuál es la especificidad?","difficulty":"avanzado","options":["75%","60%","90%","25%"],"correct_index":0,"rationale":"Especificidad = verdaderos negativos / total sin enfermedad = 90/120 = 75%. No debe confundirse con valor predictivo negativo.","reference_hint":"Consultar textos vigentes de epidemiología clínica y salud pública."},{"slug":"sp-prevalencia","area":"salud_publica","topic":"Valores predictivos","vignette":"Dos poblaciones reciben la misma prueba con sensibilidad y especificidad constantes; la segunda tiene prevalencia de la enfermedad mucho menor.","prompt":"¿Qué sucede con el valor predictivo positivo?","difficulty":"intermedio","options":["Siempre aumenta","Permanece igual","Disminuye cuando baja prevalencia","Se vuelve la sensibilidad"],"correct_index":2,"rationale":"Al disminuir la prevalencia, disminuye la proporción de verdaderos positivos entre los resultados positivos y cae el valor predictivo positivo.","reference_hint":"Consultar textos vigentes de epidemiología clínica y salud pública."},{"slug":"sp-prevencion","area":"salud_publica","topic":"Prevención primaria","vignette":"Un centro de salud organiza vacunación dirigida a personas susceptibles que aún no presentan la enfermedad para evitar casos nuevos.","prompt":"¿Qué nivel de prevención representa?","difficulty":"intermedio","options":["Prevención terciaria","Prevención primaria","Prevención secundaria","Rehabilitación"],"correct_index":1,"rationale":"La vacunación para evitar la aparición de enfermedades constituye prevención primaria; la detección temprana y el manejo de secuelas pertenecen a otros niveles.","reference_hint":"Consultar textos vigentes de epidemiología clínica y salud pública."}]$enarmcases$::jsonb) AS x(
 slug text,area text,topic text,difficulty text,vignette text,prompt text,
 options jsonb,correct_index integer,rationale text,reference_hint text)
ON CONFLICT (slug) DO NOTHING;
COMMIT;
